import 'dart:convert' show utf8;
import 'package:chewie/chewie.dart';
import 'package:flutter/material.dart';
import 'package:flutter_subtitle/flutter_subtitle.dart' hide Subtitle;
import 'package:video_player/video_player.dart';
import 'package:http/http.dart' as http;

// inside your widget
final body = utf8.decode((await http.get(Uri.parse('https://example.com/subtitles.vtt'))).bodyBytes);
final subtitleController = SubtitleController.string(body, format: SubtitleFormat.webvtt);
final videoController = VideoPlayerController.networkUrl(Uri.parse('https://example.com/video.mp4'));
await videoController.initialize();
final chewieController = ChewieController(
  videoPlayerController: videoController,
  subtitleBuilder: (context, subtitle) => SubtitleView(text: subtitle),
);
chewieController.setSubtitle(subtitleController.subtitles.map((e) => Subtitle(index:e.number,start:Duration(milliseconds:e.start),end:Duration(milliseconds:e.end),text:e.text)).toList());
